-- HORIZON — base de conocimiento inicial del agente (correr DESPUÉS de la migración 013)
-- Idempotente: si un slug ya existe NO se sobrescribe (lo que edites en OPS se respeta).
insert into public.kb_items (slug, tipo, categoria, titulo, contenido, variantes, keywords, link, auto) values
('kw-contexto','palabra_clave','recursos','CONTEXTO','¡Acá está! 🧠 Completa tu ficha de contexto en 5 minutos y te entrego el texto listo para pegar en ChatGPT, Claude o Gemini: https://horizonweb.cl/recursos/contexto','{}'::text[],array['contexto']::text[],'https://horizonweb.cl/recursos/contexto',true),
('kw-prompts','palabra_clave','recursos','PROMPTS','¡Te los dejo! 📌 Cuéntame cómo hablas y qué te preguntan, y te devuelvo los 3 prompts adaptados a tu negocio: https://horizonweb.cl/recursos/prompts','{}'::text[],array['prompts','prompt']::text[],'https://horizonweb.cl/recursos/prompts',true),
('kw-ficha','palabra_clave','recursos','FICHA','¡Vamos! ✅ Marca lo que ya tiene tu ficha de Google y en 2 minutos te digo en qué nivel estás y qué arreglar primero: https://horizonweb.cl/recursos/ficha','{}'::text[],array['ficha','checklist']::text[],'https://horizonweb.cl/recursos/ficha',true),
('kw-auditoria','palabra_clave','recursos','AUDITORÍA','¡Genial! 🔎 Responde 10 preguntas y te entrego tu mini-auditoría con puntaje, tus 3 prioridades y qué camino te conviene: https://horizonweb.cl/recursos/auditoria. Cuando la tengas, si quieres la conversamos.','{}'::text[],array['auditoria','auditoría']::text[],'https://horizonweb.cl/recursos/auditoria',true),
('kw-lista','palabra_clave','fundadores','LISTA','Te anoto en la lista del Programa Fundadores 🙌 Son 3 cupos para negocios de Rancagua: mismo precio, segundo mes de soporte sin costo y el valor del soporte congelado por 12 meses. Cuéntame: ¿cómo se llama tu negocio y a qué se dedica?','{}'::text[],array['lista','fundador','fundadores']::text[],null,true),
('precios','respuesta','precios','¿Cuánto cuesta? / Precios','Tenemos 4 planes (pago único + boleta):
• Plan 01 · Presencia Digital: $490.000 — página web profesional, Google y WhatsApp.
• Plan 02 · Ecosistema Digital: $990.000 — web + sistema (reservas, tienda o caja) + CRM.
• Plan 03 · Sistema con IA: $1.990.000 — todo lo anterior + agente IA, automatizaciones y Meta Ads.
• Plan 04 · Agente IA Personalizado: desde $1.490.000 — atiende WhatsApp, Instagram y web 24/7.
El primer mes de soporte va incluido. ¿Qué tipo de negocio tienes? Así te digo cuál calza.',array['cuánto cobras','qué precio tiene','valores','cuánto sale una web','tarifas','cotización']::text[],array['precio','precios','cuanto','cuánto','valor','cobras','cotizar','cotizacion']::text[],'https://horizonweb.cl/servicios',true),
('plan-01','respuesta','planes','Plan 01 · Presencia Digital','El Plan 01 ($490.000 + boleta, 3–4 semanas) es tu página web profesional en dominio propio, conectada a Google y WhatsApp: hasta 5 secciones, ficha de Google optimizada, WhatsApp Business configurado, chatbot básico 24/7 y formulario que te avisa de cada contacto. Soporte desde $120.000/mes (el primer mes va incluido).',array['solo quiero una página web','web simple','página web básica']::text[],array['web','pagina','página','sitio','presencia']::text[],'https://horizonweb.cl/plan-01',true),
('plan-02','respuesta','planes','Plan 02 · Ecosistema Digital','El Plan 02 ($990.000 + boleta, 4–5 semanas) es la web + un sistema para ordenar tu negocio: reservas online, tienda o caja con inventario (se elige uno), CRM con dashboard de métricas y chatbot completo que registra a cada cliente. Ideal si hoy tienes todo en cuadernos o en la memoria. Soporte desde $200.000/mes.',array['sistema de pedidos','crm','ordenar el negocio','sistema de reservas','tienda online']::text[],array['sistema','crm','reservas','pedidos','tienda','inventario','caja','ordenar']::text[],'https://horizonweb.cl/plan-02',true),
('plan-03','respuesta','planes','Plan 03 · Sistema con IA','El Plan 03 ($1.990.000 + boleta, 5–6 semanas) es el sistema completo con IA: todo el Plan 02, más un agente IA que atiende WhatsApp, Instagram y web, automatizaciones (cotizaciones, recordatorios, reportes), campañas de Meta Ads gestionadas y una auditoría completa del negocio. Para cuando tú eres el cuello de botella. Soporte desde $350.000/mes.',array['sistema con inteligencia artificial','automatizar todo']::text[],array['automatizacion','automatización','ads','completo']::text[],'https://horizonweb.cl/plan-03',true),
('plan-04','respuesta','planes','Plan 04 · Agente IA Personalizado','El Plan 04 (desde $1.490.000 + boleta, 2–3 semanas) es un empleado virtual 24/7: un agente entrenado con la información real de tu negocio que responde en WhatsApp, Instagram y web, agenda, responde objeciones y deriva a una persona cuando hace falta. Se puede contratar solo o sumado a otro plan. Soporte $290.000/mes. Ojo: el consumo de WhatsApp API y del modelo de IA lo cobra el proveedor aparte (te lo estimo antes de partir).',array['bot de whatsapp','chatbot','asistente virtual','alguien que responda los mensajes']::text[],array['agente','bot','chatbot','ia','responda','24/7']::text[],'https://horizonweb.cl/plan-04',true),
('cual-plan','respuesta','planes','¿Qué plan me conviene?','Depende de dónde está tu negocio hoy. La forma más rápida de saberlo: haz la mini-auditoría (4 minutos) y te dice qué camino te conviene: https://horizonweb.cl/recursos/auditoria. Si prefieres, cuéntame a qué se dedica tu negocio y cómo recibes hoy a tus clientes.',array['cuál me recomiendas','qué necesito','no sé qué necesito']::text[],array['conviene','recomiendas','necesito']::text[],'https://horizonweb.cl/recursos/auditoria',true),
('plazos','respuesta','proceso','¿Cuánto se demoran?','Entre 2 y 6 semanas según el plan: Agente IA 2–3, Presencia Digital 3–4, Ecosistema Digital 4–5 y Sistema con IA 5–6. Desde el día 1 tienes un cronograma con hitos claros.',array['en cuánto tiempo está lista','cuánto demora','plazo de entrega']::text[],array['demora','plazo','tiempo','semanas','cuando','cuándo']::text[],null,true),
('pago','respuesta','proceso','Formas de pago','Se paga en 2 partes: 50% al firmar (ahí partimos) y 50% contra entrega, con el proyecto publicado y funcionando. Es por transferencia y con boleta de honorarios.',array['cómo se paga','puedo pagar en cuotas','aceptan tarjeta']::text[],array['pago','pagar','cuotas','transferencia','tarjeta','abono']::text[],null,true),
('cuotas-extra','politica','proceso','Más cuotas o descuentos','Los precios son fijos y se pagan 50/50. Si necesitas otra modalidad, lo conversa Benjamín directamente contigo.',array['me haces descuento','lo puedo pagar en 3 cuotas','precio especial']::text[],array['descuento','rebaja','oferta','3 cuotas','4 cuotas']::text[],null,false),
('soporte','respuesta','proceso','Soporte mensual','Después de la entrega, el primer mes de soporte va incluido. Desde el segundo es opcional y mes a mes, sin permanencia: soporte directo, hosting, monitoreo, cambios menores y reporte mensual. Va desde $120.000 (Plan 01) hasta $350.000 (Plan 03).',array['tiene mensualidad','qué pasa después de la entrega','mantención']::text[],array['mensual','mensualidad','mantencion','mantención','soporte','hosting']::text[],null,true),
('dominio','respuesta','proceso','Dominio y hosting','El dominio (tunegocio.cl) y el hosting quedan a tu nombre: son tuyos. Su costo lo pagas directo al proveedor (un dominio .cl cuesta alrededor de $10.000 al año) y yo me encargo de configurarlo todo.',array['la página queda a mi nombre','de quién es la web']::text[],array['dominio','hosting','.cl','a mi nombre']::text[],null,true),
('fuera-rancagua','respuesta','general','¿Trabajan fuera de Rancagua?','Sí. La base es Rancagua, pero trabajo con negocios de toda la Región de O’Higgins y Santiago. Casi todo es remoto; la instalación final la hago en persona cuando se puede.',array['atienden en santiago','son de rancagua']::text[],array['rancagua','santiago','machali','machalí','region','región','donde','dónde']::text[],null,true),
('quien','respuesta','general','¿Qué es HORIZON? / ¿Quién eres?','Soy Benjamín, diseñador digital de Rancagua y fundador de HORIZON. Ayudamos a negocios locales a crecer sin caos: web, sistemas para ordenar el negocio e inteligencia artificial que atiende por ti. Todo hecho a la medida de tu negocio, no plantillas.',array['qué hacen','a qué se dedican','quién está detrás']::text[],array['horizon','quien','quién','eres']::text[],null,true),
('diagnostico','respuesta','proceso','Diagnóstico gratuito / agendar','El diagnóstico es gratis y sin compromiso: 30 minutos para entender tu negocio y ver qué te conviene. Puedes agendarlo acá: https://horizonweb.cl/agendar',array['quiero una reunión','podemos conversar','agendar llamada']::text[],array['reunion','reunión','llamada','agendar','diagnostico','diagnóstico','conversar']::text[],'https://horizonweb.cl/agendar',true),
('fundadores','respuesta','fundadores','Programa Fundadores','Este trimestre trabajo con 3 negocios fundadores de Rancagua. No es descuento: es el mismo precio, con beneficios — segundo mes de soporte sin costo, valor del soporte congelado por 12 meses, sesión de resultados a los 60 días y atención prioritaria. A cambio pido un testimonio en video y permiso para mostrar el proceso.',array['qué es lo de fundadores','quedan cupos']::text[],array['fundador','fundadores','cupos','cupo']::text[],null,true),
('garantia','respuesta','proceso','¿Qué garantía tengo?','Cada etapa tiene hasta 2 rondas de revisión, y si al final algo no cumple lo acordado en el brief, se corrige sin costo. La propuesta deja por escrito exactamente qué se entrega. Lo que no puedo garantizar son ventas o posiciones exactas en Google, porque dependen de factores externos; sí trabajamos para mejorarlas y medirlas.',array['y si no me gusta','qué pasa si no funciona']::text[],array['garantia','garantía','no me gusta','asegura']::text[],null,true),
('reembolso','politica','proceso','Reembolsos y término anticipado','El pago inicial no es reembolsable una vez hecho el kickoff, porque corresponde a trabajo ya iniciado. Si el proyecto se detiene, se paga solo la proporción avanzada. Los detalles quedan en el contrato.',array['me devuelven la plata','puedo cancelar']::text[],array['reembolso','devolucion','devolución','cancelar','arrepiento']::text[],null,false),
('materiales','respuesta','proceso','¿Qué necesito tener?','Lo básico: tu logo (si no tienes, trabajamos con tipografía), fotos de tu local o productos, tu lista de servicios y precios, y acceso a tu Google, WhatsApp e Instagram. Si te falta algo, lo resolvemos en el camino.',array['necesito logo','qué tengo que entregar']::text[],array['logo','fotos','necesito tener','entregar']::text[],null,true),
('apps-delivery','respuesta','resultados','Comisiones de apps de delivery','Las apps como PedidosYa, Uber Eats o Rappi se quedan con cerca de un 30% de cada pedido. Con una web y un sistema de pedidos propio (Plan 02), cada cliente que pide directo te deja ese 30% a ti. Si solo 1 de cada 5 pedidos se pasa a tu canal, la inversión se paga en pocos meses.',array['pedidosya me cobra mucho','quiero dejar uber eats','sistema de delivery propio']::text[],array['pedidosya','uber','rappi','delivery','comision','comisión','despacho']::text[],'https://horizonweb.cl/plan-02',true),
('redes','respuesta','servicios','¿Manejan redes sociales?','No hago gestión diaria de redes. El Plan 02 incluye un plan de contenido para que sepas qué publicar, y el Plan 03 incluye campañas de Meta Ads gestionadas. El foco de HORIZON es que tu negocio tenga un sistema que capte y atienda clientes.',array['me manejan el instagram','community manager','hacen publicaciones']::text[],array['redes','instagram','publicaciones','community','contenido']::text[],null,true),
('identidad','politica','servicios','Logo o identidad visual por separado','Hoy la identidad visual no se ofrece como servicio aparte; se trabaja dentro de los planes. Si es lo único que necesitas, Benjamín te puede orientar.',array['solo necesito un logo','me hacen un logo']::text[],array['logo nuevo','identidad','branding','marca']::text[],null,false),
('cambios-despues','respuesta','proceso','Cambios después de la entrega','Con el soporte mensual tienes cambios menores incluidos (textos, fotos, precios, horarios). Cambios grandes, como una sección nueva o un sistema adicional, se cotizan aparte.',array['puedo cambiar cosas después','si quiero agregar algo']::text[],array['cambios','modificar','agregar','actualizar']::text[],null,true),
('ejemplos','respuesta','general','Ejemplos de trabajos','Un ejemplo en producción es Vitalkine (vitalkine.com): sitio a medida con sistema de reservas, dominio propio y SEO local. Puedes ver más en https://horizonweb.cl/#portfolio',array['tienes ejemplos','qué has hecho','portafolio']::text[],array['ejemplos','portafolio','trabajos','clientes']::text[],'https://horizonweb.cl/#portfolio',true),
('atencion','respuesta','general','Horario de atención','Respondo de lunes a viernes de 9:00 a 19:00. Fuera de ese horario te responde este asistente, y si necesitas a Benjamín, le aviso para que te escriba apenas pueda.',array['a qué hora atienden','están disponibles']::text[],array['horario','atienden','disponible']::text[],null,true),
('humano','respuesta','general','Hablar con una persona','Claro, le aviso a Benjamín para que te escriba él directamente 🙌 ¿Me dejas tu nombre y el de tu negocio?',array['quiero hablar con alguien','eres un bot','hablar con benjamín']::text[],array['persona','humano','benjamin','benjamín','bot','robot']::text[],null,true),
('seo-local','glosario','glosario','SEO local','Es lo que hace que aparezcas en Google cuando alguien busca tu rubro en tu comuna, por ejemplo “panadería en Rancagua”. Depende de tu ficha de Google, tus reseñas y que tu web diga claramente qué haces y dónde.','{}'::text[],array['seo','posicionamiento','aparecer en google']::text[],null,true),
('geo','glosario','glosario','GEO (optimización para IA)','Es preparar la información de tu negocio para que ChatGPT, Gemini o Perplexity te recomienden cuando alguien les pregunta. Cada vez más gente busca así, no solo en Google.','{}'::text[],array['geo','chatgpt me recomiende']::text[],null,true),
('ficha-google','glosario','glosario','Ficha de Google (Google Business Profile)','Es el perfil de tu negocio que aparece en Google y Google Maps: dirección, horario, fotos, reseñas y teléfono. Es gratis y suele ser lo primero que ve un cliente.','{}'::text[],array['ficha','google maps','perfil de empresa']::text[],null,true),
('landing','glosario','glosario','Landing page','Una página web enfocada en una sola acción: que el cliente te escriba, reserve o compre. Es más directa que un sitio con muchas secciones.','{}'::text[],array['landing']::text[],null,true),
('dominio-gl','glosario','glosario','Dominio','Es la dirección de tu web, por ejemplo tunegocio.cl. Se paga una vez al año y queda a tu nombre.','{}'::text[],array['dominio']::text[],null,true),
('hosting-gl','glosario','glosario','Hosting','Es el “arriendo” del espacio donde vive tu web en internet para que esté disponible las 24 horas.','{}'::text[],array['hosting','servidor']::text[],null,true),
('crm','glosario','glosario','CRM','Es una lista ordenada de tus clientes: quién te compró, cuándo, qué y cómo contactarlo. Reemplaza el cuaderno y te permite hacer que vuelvan.','{}'::text[],array['crm','base de clientes']::text[],null,true),
('dashboard','glosario','glosario','Dashboard','Un tablero que te muestra tu negocio en números: ventas, pedidos, de dónde llegan tus clientes. Para decidir con datos, no a ojo.','{}'::text[],array['dashboard','tablero','metricas','métricas']::text[],null,true),
('chatbot-vs-agente','glosario','glosario','Chatbot vs. agente IA','Un chatbot responde preguntas fijas. Un agente IA entiende lo que le escriben, conoce tu negocio, agenda, responde objeciones y deriva a una persona cuando hace falta.','{}'::text[],array['chatbot','agente']::text[],null,true),
('automatizacion','glosario','glosario','Automatización','Que una tarea repetitiva se haga sola: confirmar reservas, mandar recordatorios, avisarte de un pedido o registrar a un cliente nuevo.','{}'::text[],array['automatizar','automatico','automático']::text[],null,true),
('n8n','glosario','glosario','n8n','Es la herramienta que usamos para conectar tus apps entre sí (WhatsApp, planillas, correo, tu web) y armar automatizaciones sin depender de una persona.','{}'::text[],array['n8n']::text[],null,true),
('wa-business','glosario','glosario','WhatsApp Business vs. WhatsApp API','WhatsApp Business es la app gratis con catálogo y respuestas rápidas. La API de WhatsApp permite que un sistema o agente IA responda por ti; tiene un costo por conversación que cobra Meta.','{}'::text[],array['whatsapp business','api de whatsapp']::text[],null,true),
('meta-ads','glosario','glosario','Meta Ads','Publicidad pagada en Instagram y Facebook. Tú decides cuánto invertir y se le muestra a las personas correctas de tu zona.','{}'::text[],array['publicidad','anuncios','ads']::text[],null,true),
('boleta','glosario','glosario','Boleta de honorarios','Los precios se documentan con boleta de honorarios. Si tu negocio es empresa, retiene el 15,25% y lo paga al SII; si eres persona natural sin obligación de retener, pagas el monto bruto.','{}'::text[],array['boleta','factura','iva','retencion','retención']::text[],null,true),
('contexto-ia','glosario','glosario','Contexto para tu IA','Es la información de tu negocio (qué vendes, dónde estás, cómo hablas) que le das a ChatGPT, Claude o Gemini para que responda como tu negocio y no de forma genérica.','{}'::text[],array['contexto']::text[],null,true),
('prompt','glosario','glosario','Prompt','Es la instrucción que le escribes a una IA. Mientras más claro y con más contexto, mejor la respuesta.','{}'::text[],array['prompt']::text[],null,true),
('canal-propio','glosario','glosario','Canal propio','Tu web, tu WhatsApp y tu base de clientes: canales que controlas tú, sin pagar comisión por cada venta como en las apps.','{}'::text[],array['canal propio']::text[],null,true),
('resenas','glosario','glosario','Reseñas','Las opiniones de tus clientes en Google. Más reseñas y respondidas = más confianza y mejor posición en Maps.','{}'::text[],array['reseñas','resenas','opiniones','estrellas']::text[],null,true),
('obj-caro','objecion','objeciones','Es caro','Te entiendo. Piénsalo como inversión, no como gasto: si hoy pierdes clientes porque no te encuentran o no alcanzas a responder, eso cuesta todos los meses. Por eso parto con un diagnóstico gratis: vemos cuánto te está costando hoy y si el plan se paga solo. ¿Lo agendamos?',array['es muy caro','no tengo presupuesto','está caro']::text[],array['caro','presupuesto','plata','dinero']::text[],null,true),
('obj-instagram','objecion','objeciones','Ya tengo Instagram','Instagram es clave, pero no es tuyo y no te ordena el negocio: no aparece bien en Google, no guarda a tus clientes y depende del algoritmo. La web y el sistema trabajan con tu Instagram, no en su contra.',array['con instagram me basta','no necesito web']::text[],array['basta','no necesito']::text[],null,true),
('obj-tiempo','objecion','objeciones','No tengo tiempo','Justamente por eso: el sistema está pensado para quitarte trabajo, no para sumarte. Yo me encargo de casi todo; de ti necesito unas 2 horas en total, repartidas en el proyecto.',array['no tengo tiempo para esto','ando muy ocupado']::text[],array['tiempo','ocupado','ocupada']::text[],null,true),
('obj-sobrino','objecion','objeciones','Un conocido me lo hace','¡Puede ser una buena opción para partir! La diferencia es que acá no es solo una web: es un sistema conectado a Google, WhatsApp y tus clientes, con soporte y responsable por escrito.',array['mi sobrino me hace la página','un amigo me la hace']::text[],array['sobrino','amigo','conocido','primo']::text[],null,true),
('obj-ia-mal','objecion','objeciones','¿Y si la IA responde mal?','El agente responde solo lo que está en la base de tu negocio, y lo que no sabe te lo deriva a ti. Revisamos sus conversaciones cada semana el primer mes para ajustarlo.',array['me da miedo la ia','la ia se equivoca']::text[],array['equivoca','miedo','confio','confío']::text[],null,true),
('obj-pensar','objecion','objeciones','Lo voy a pensar','¡Claro! Para ayudarte a decidir: ¿qué es lo que más te hace dudar, el precio, el tiempo o si te va a servir? Así te mando la info justa.',array['lo pienso','te aviso','déjame pensarlo']::text[],array['pensar','pienso','aviso','despues','después']::text[],null,true),
('pol-no-prometer','politica','reglas','Nunca prometer resultados','Nunca prometer ventas, posiciones en Google ni plazos distintos a los oficiales. Nunca inventar precios, descuentos ni condiciones.','{}'::text[],'{}'::text[],null,false),
('pol-datos','politica','reglas','Datos personales','No pedir RUT, datos bancarios ni contraseñas por chat. Para accesos, Benjamín lo coordina en el kickoff.','{}'::text[],'{}'::text[],null,false)
on conflict (slug) do nothing;
